let nextId = 1;

export async function listTools() {
  return [
    {
      name: 'ticket_create',
      description: 'Create a support ticket with a title and description.',
      inputSchema: {
        type: 'object',
        properties: {
          title: { type: 'string', description: 'Short summary of the issue.' },
          description: { type: 'string', description: 'Detailed description of the issue.' },
          priority: { type: 'string', enum: ['low', 'normal', 'high'], description: 'Ticket priority. Defaults to normal.' }
        },
        required: ['title', 'description'],
        additionalProperties: false
      }
    }
  ];
}

export async function callTool(name, args = {}) {
  if (name !== 'ticket_create') {
    throw new Error(`Unknown tool: ${name}`);
  }

  // Reject extra fields
  const allowed = new Set(['title', 'description', 'priority']);
  for (const key of Object.keys(args)) {
    if (!allowed.has(key)) {
      throw new Error(`Unknown argument: ${key}`);
